{
  "technical_and_design_decisions": [
    "Migrate each Spring XD module into a standalone Spring Boot application starter following the Spring Cloud Stream app-starter conventions: a core library (auto-configuration + properties) plus a thin executable app per module.",
    "Implement modules on the current baseline implied by the specification: Spring Framework 6.x, Spring Boot 3.x, Spring Cloud Stream 4.x, Java 17.",
    "Reuse the existing Spring Integration channel adapters/handlers used by the XD modules (syslog inbound adapter, IMAP/mail adapters, TCP inbound adapters and connection factories, Gpfdist message handler, HDFS dataset writer, Mongo outbound adapter) and repackage them instead of rewriting from scratch.",
    "Replace XD module options and option metadata with typed @ConfigurationProperties classes, with metadata generated via spring-boot-configuration-processor.",
    "Wire each module to the Spring Cloud Stream binding model (functional bean style: Supplier for sources, Consumer for sinks) so modules are binder-agnostic (Kafka/Rabbit).",
    "Each module gets its own Maven module, unit tests (JUnit 5, Mockito), integration tests (Testcontainers/Docker or embedded servers: GreenMail for mail, embedded Mongo or Testcontainers, in-memory TCP/syslog endpoints, HDFS MiniCluster), and an Asciidoc README documenting options.",
    "Common conventions (naming, package layout under org.springframework.cloud.stream.app.*, parent POM, code style) are established once and reused for all 8 modules."
  ],
  "assumptions": [
    "All development work is performed personally by one experienced developer; estimates are effort (workdays), not calendar time, and exclude waiting time (code review queues, CI backlog).",
    "The original Spring XD module source code, tests, and documentation are available and can be consulted freely.",
    "The target 's-c-s' repository (spring-cloud-stream app starters) exists with a parent build, contribution guidelines, and release process to plug into.",
    "External systems needed for testing (mail server, MongoDB, gpfdist/Greenplum emulator, HDFS) can be satisfied with embedded servers, Docker/Testcontainers, or MiniCluster locally; no provisioning of real infrastructure is required.",
    "No UI, security hardening audits, performance benchmarking, or production deployment work is in scope; scope ends at merged, tested, documented, releasable modules.",
    "Kafka and Rabbit binders are available for end-to-end pipeline verification via Testcontainers or existing shared test infrastructure.",
    "Effort per module includes porting code, writing configuration properties/metadata, unit tests, and module-level integration tests."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Analysis and migration design",
      "activity_description": "Review the 8 XD modules (syslog, mail, tcp, tcp-client, gpfdist, hdfs-dataset, mongo), map XD options to configuration properties, and define the common migration pattern (package layout, binding style, properties conventions, testing strategy).",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Repository and build scaffolding",
      "activity_description": "Create Maven module structure under the s-c-s app-starters repo, parent POMs, dependency management, code style/check configuration, and skeleton app-starter packaging to be reused by all modules.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "Migrate syslog source (U1)",
      "activity_description": "Port XD syslog module to a Spring Cloud Stream source: auto-configuration, typed properties (host, port, protocol UDP/TCP, buffer sizes), Supplier/binding wiring, unit and integration tests with in-memory syslog endpoints, module README.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "Migrate mail source (U2)",
      "activity_description": "Port XD mail source module: IMAP-idle/polling inbound adapter configuration, properties (store URL, folder, credentials, polling options), binding wiring, tests using GreenMail, module README.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "Migrate tcp source (U3)",
      "activity_description": "Port XD tcp source module: TCP server inbound adapter and connection factory configuration, serializers/deserializers, properties (port, framing, socket options), binding wiring, unit and socket-level integration tests, module README.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A6",
      "activity_name": "Migrate tcp-client source (U4)",
      "activity_description": "Port XD tcp-client source module: client connection factory, reconnect/retry behavior, serializers, properties, binding wiring, tests against a local TCP echo/test server, module README.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A7",
      "activity_name": "Migrate gpfdist sink (U5)",
      "activity_description": "Port XD gpfdist sink module: Gpfdist message handler and its embedded HTTP server, Greenplum gpfdist protocol handling, flush/segment logic, properties (host, port, batch, delimiter, column mapping), binding wiring, tests against a gpfdist client/test double, module README. High complexity due to protocol and server lifecycle.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A8",
      "activity_name": "Migrate hdfs-dataset sink (U6)",
      "activity_description": "Port XD hdfs-dataset sink module: dataset (Avro/Parquet) writing via the dataset SDK, partitioning and rollover, properties (FS URI, format, partition keys, batch size), binding wiring, integration tests against HDFS MiniCluster, module README. High complexity due to Hadoop dependencies and test environment.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A9",
      "activity_name": "Migrate mail sink (U7)",
      "activity_description": "Port XD mail sink module: SMTP outbound adapter configuration, properties (host, port, auth, from/to/subject templating), binding wiring, tests using GreenMail, module README.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A10",
      "activity_name": "Migrate mongo sink (U8)",
      "activity_description": "Port XD mongo sink module: Mongo outbound adapter/message handler, properties (URI, database, collection, write concern), binding wiring, tests against embedded or Testcontainers MongoDB, module README.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A11",
      "activity_name": "Cross-module integration and end-to-end verification",
      "activity_description": "Verify each migrated module runs as a standalone app in real streaming pipelines with Kafka and Rabbit binders (Testcontainers/local Docker): source-to-sink flows, serialization checks, error/restart behavior; fix integration defects.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A12",
      "activity_name": "Reference documentation",
      "activity_description": "Write/aggregate Asciidoc reference documentation for all 8 app starters (options tables generated from properties metadata, usage examples) and update the repo-level index/readme.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A13",
      "activity_name": "CI and release configuration",
      "activity_description": "Add the new modules to CI build plans, configure test execution for Docker-based suites, artifact publishing, and release/milestone configuration for the new starters.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A14",
      "activity_name": "Review, refactoring and hardening",
      "activity_description": "Self-review and peer-review iterations across all modules: align naming/conventions, remove XD-isms, add missing metadata and validation, address review feedback, stabilize flaky tests, final polish before merge/release.",
      "most_likely_effort": 5
    }
  ],
  "reported_total": {
    "most_likely_effort": 66
  }
}
